solution.solution.cpp:
#include <string>

struct PathParts { std::string folder; std::string stem; std::string extension; };

PathParts splitPath(const std::string& path)
{
    PathParts parts;
    const std::size_t slash{ path.find_last_of("\\/") };
    std::string name;
    if (slash == std::string::npos)
    {
        name = path;
    }
    else
    {
        parts.folder = path.substr(0, slash);
        name = path.substr(slash + 1);
    }

    const std::size_t dot{ name.find_last_of('.') };
    if (dot == std::string::npos || dot == 0)
    {
        parts.stem = name;
    }
    else
    {
        parts.stem = name.substr(0, dot);
        parts.extension = name.substr(dot);
    }
    return parts;
}

unitTests:
static bool is(const PathParts& p, const char* folder, const char* stem, const char* ext) { return p.folder == folder && p.stem == stem && p.extension == ext; }
TEST("a full Windows path") { CHECK(is(splitPath("C:\\Games\\Save\\slot1.sav"), "C:\\Games\\Save", "slot1", ".sav")); }
TEST("forward slashes and two dots") { CHECK(is(splitPath("levels/forest.v2.lvl"), "levels", "forest.v2", ".lvl")); }
TEST("no folder, no extension") { CHECK(is(splitPath("README"), "", "README", "")); }
TEST("a leading dot is not an extension") { CHECK(is(splitPath("C:\\Users\\.config"), "C:\\Users", ".config", "")); }
TEST("dots in the folder do not count") { CHECK(is(splitPath("C:\\my.games\\save"), "C:\\my.games", "save", "")); }
TEST("mixed separators") { CHECK(is(splitPath("C:\\games/mods\\a.dll"), "C:\\games/mods", "a", ".dll")); }
TEST("a trailing dot") { CHECK(is(splitPath("odd."), "", "odd", ".")); }
TEST("an empty path") { CHECK(is(splitPath(""), "", "", "")); }

